// ---- Structs with owned data ----
struct Player {
    name: String,      // Owned
    health: i32,       // Copy
    items: Vec<String>, // Owned
}

// ---- Structs with borrowed data ----
// Use lifetimes to specify how long the borrow lasts
struct BorrowedPlayer<'a> {
    name: &'a str,      // Borrowed
    health: i32,
}

fn main() {
    // ---- Creating a struct with owned data ----
    let mut player1 = Player {
        name: String::from("Hero"),
        health: 100,
        items: vec![String::from("Sword"), String::from("Shield")],
    };

    println!("Player: {}", player1.name);
    println!("Health: {}", player1.health);
    println!("Items: {:?}", player1.items);

    // ---- Modifying a struct's owned data ----
    player1.name.push_str(" the Brave");
    player1.health -= 20;
    player1.items.push(String::from("Potion"));

    println!("\nAfter modifications:");
    println!("Player: {}", player1.name);
    println!("Health: {}", player1.health);
    println!("Items: {:?}", player1.items);

    // ---- Moving ownership out of a struct ----
    let name = player1.name;  // Moves name out of player1
    // println!("{}", player1.name);  // ERROR! name was moved
    println!("Moved name: {}", name);

    // ---- Creating a struct with borrowed data ----
    let name_str = String::from("Aragorn");
    let player2 = BorrowedPlayer {
        name: &name_str,  // Borrows from name_str
        health: 120,
    };
    println!("\nBorrowed Player: {}", player2.name);
    // name_str is still valid here

    // ---- Struct with mutable borrow ----
    let mut player3 = Player {
        name: String::from("Gandalf"),
        health: 80,
        items: vec![],
    };

    // Mutable borrow of a field
    let name_ref = &mut player3.name;
    name_ref.push_str(" the Grey");
    println!("\nPlayer3 name: {}", name_ref);
    // name_ref goes out of scope here

    // Now we can use player3 again
    println!("Player3 health: {}", player3.health);
}

// ---- Function taking ownership of a struct ----
fn take_player(player: Player) {
    println!("take_player: {}", player.name);
}  // player is dropped here

// ---- Function borrowing a struct ----
fn borrow_player(player: &Player) {
    println!("borrow_player: {}", player.name);
}

// ---- Function mutably borrowing a struct ----
fn modify_player(player: &mut Player) {
    player.health -= 10;
    player.items.push(String::from("Health Potion"));
}

// ---- Returning a struct ----
fn create_player(name: String) -> Player {
    Player {
        name,
        health: 100,
        items: Vec::new(),
    }
}

